            &lt;/div&gt;
            &lt;form action=&quot;http://localhost:8080/gaming/sessions/add-food&quot; id=&quot;addFoodForm&quot; method=&quot;post&quot; accept-charset=&quot;utf-8&quot;&gt;
                &lt;input type=&quot;hidden&quot; name=&quot;csrf_test_name&quot; value=&quot;a1acd9149443e0ca78590a93b7726107&quot;&gt;                &lt;input type=&quot;hidden&quot; name=&quot;gaming_visit_id&quot; id=&quot;addFoodVisitId&quot; value=&quot;&quot;&gt;
